# Per-row evidence is an explanation of the actual review, with original text retained where sound.
patches=[];reads=[]
for s in a['subjects']:
 id=s['id'];n=notes[id]; src=pathlib.Path(s['source']); raw=src.read_bytes(); txt=raw.decode()
 contract=json.load(open(s['contract']))['contracts'][id]
 current={r['case']:r for r in contract['boundaries']}
 read={'id':id,'source':s['source'],'sections_read':re.findall(r'^## (.+)$',txt,re.M),'review':n,'candidate_cases':[r['original']['case'] for r in s['rows']]}
 reads.append(read)
 for r in s['rows']:
  c=r['original']['case'];original=current[c]
  assert original==r['original'],(id,c,'worklist is stale')
  proposed=copy.deepcopy(fix.get((id,c),original))
  # Preserve any rich prior evidence/fields; only disposition fields are replaced when corrected.
  if (id,c) in fix:
   merged=copy.deepcopy(original)
   merged.pop('reason',None);merged.pop('evidence',None)
   merged.update(proposed);proposed=merged
  if c.startswith('iff'):
   why=n['logical_form']+' '+n['mathematical_review']
  elif c=='nonempty-choice':why=n['choice_review']+' '+n['mathematical_review']
  elif c=='empty':why=n['domain']+' '+n['mathematical_review']
  elif c=='endpoints':why=n['mathematical_review']+' '+n['domain']
  else:why=n['domain']+' '+n['mathematical_review']
  if (id,c) in fix:why=fix[(id,c)].get('reason',fix[(id,c)].get('evidence'))
  kinds={x['kind'] for x in r['candidate_findings']}
  if 'template' in kinds:proposed['template_review']={'upheld':True,'by':'math81_boundary_classical_low','reason':why}
  if 'contradicted' in kinds and proposed['status']=='not_applicable':
   proposed['reviewed']={'upheld':True,'by':'math81_boundary_classical_low','reason':why}
  patches.append({'id':id,'case':c,'contract':s['contract'],'source':s['source'],'original_current_row':original,'proposed_full_row':proposed,'evidence':{'mathematical_case_review':why,'disposition_changed':(id,c) in fix,'candidate_findings':r['candidate_findings']}})
assert len(patches)==462 and len(reads)==109,(len(patches),len(reads))
(OUT/'row-patches.json').write_text(json.dumps({'run':a['run'],'group':'classical_low','by':'math81_boundary_classical_low','kind':'isolated owner proposal; no final seals or gate credit','patches':patches,'item_reads':reads},indent=2)+'\n')
